import { useState } from 'react';
import { Button, Code, Group, Stack, Textarea, TextInput, Title } from '@mantine/core';
import { useForm, type FormErrors } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { OccurrencePreview } from './OccurrencePreview';
import { toEventPayload } from './payload';
import { formatOccurrence, getOccurrences, toRecurrenceRule } from './recurrence';
import { RecurrenceFields } from './RecurrenceFields';
import { ScheduleFields } from './ScheduleFields';
import type { EventPayload, RecurringEventValues } from './types';
import { useDependentFields } from './useDependentFields';
import { getDefaultTimezone, rules } from './validation';

interface RecurringEventFormProps {
  onSubmit?: (event: EventPayload) => void;
}

export function RecurringEventForm({ onSubmit }: RecurringEventFormProps) {
  const [submitted, setSubmitted] = useState<EventPayload | null>(null);

  const form = useForm<RecurringEventValues, EventPayload>({
    name: 'recurring-event',
    initialValues: {
      title: '',
      description: '',
      allDay: false,
      startDate: null,
      startTime: '',
      endDate: null,
      endTime: '',
      timezone: getDefaultTimezone(),
      location: '',
      recurrence: {
        repeat: 'none',
        interval: 1,
        weekdays: [],
        monthlyOn: 'dayOfMonth',
        ends: 'never',
        count: 10,
        until: null,
      },
      exceptions: [],
    },
    validate: rules,
    transformValues: toEventPayload,
  });

  useDependentFields(form);

  const handleSubmit = (event: EventPayload) => {
    const values = form.getValues();
    const rule = toRecurrenceRule(values.startDate, values.recurrence);
    const [first] = rule ? getOccurrences(rule, values.exceptions, 1) : [];
    const when = first
      ? formatOccurrence(first, values.allDay ? null : values.startTime)
      : 'No occurrences';

    notifications.show({ title: 'Event created', message: `${event.title} · ${when}` });
    setSubmitted(event);
    onSubmit?.(event);
  };

  // Radio and checkbox groups put data-path on their wrapper: focus the first input inside
  const handleErrors = (errors: FormErrors) => {
    const node = form.getInputNode(Object.keys(errors)[0]);
    (node?.querySelector('input') ?? node)?.focus();
  };

  return (
    <Stack gap="xl">
      <form onSubmit={form.onSubmit(handleSubmit, handleErrors)} noValidate>
        <Stack>
          <Title order={4}>Event</Title>
          <TextInput
            label="Title"
            placeholder="Title"
            withAsterisk
            {...form.getInputProps('title')}
          />
          <Textarea
            label="Description"
            placeholder="What the event is about"
            autosize
            minRows={3}
            maxRows={8}
            {...form.getInputProps('description')}
          />
          <ScheduleFields form={form} />
          <TextInput
            label="Location"
            placeholder="Room, address or meeting link"
            {...form.getInputProps('location')}
          />

          <Title order={4} mt="md">
            Recurrence
          </Title>
          <RecurrenceFields form={form} />
          <OccurrencePreview form={form} />

          <Group justify="flex-end">
            <Button type="submit">Create event</Button>
          </Group>
        </Stack>
      </form>

      {submitted && (
        <Code block aria-label="Submitted event">
          {JSON.stringify(submitted, null, 2)}
        </Code>
      )}
    </Stack>
  );
}

import { IconTrash } from '@tabler/icons-react';
import { ActionIcon, Group, Stack, Surface, Text } from '@mantine/core';
import { DatePickerInput } from '@mantine/dates';
import { formatDate, isOccurrence, toRecurrenceRule } from './recurrence';
import type { RecurringEventFormType } from './types';
import classes from './ExceptionsField.module.css';

interface ExceptionsFieldProps {
  form: RecurringEventFormType;
}

export function ExceptionsField({ form }: ExceptionsFieldProps) {
  const startDate = form.useWatchValue('startDate');
  const recurrence = form.useWatchValue('recurrence');
  const exceptions = form.useWatchValue('exceptions');
  const rule = toRecurrenceRule(startDate, recurrence);

  const addException = (date: string | null) => {
    if (!date) {
      return;
    }
    if (exceptions.includes(date)) {
      form.setFieldError('exceptions', `${formatDate(date)} is already skipped`);
      return;
    }
    form.setFieldValue('exceptions', [...exceptions, date].sort());
  };

  return (
    <Stack gap="xs">
      {/* The picker only adds dates: its own value stays empty, the list below holds the field */}
      <DatePickerInput
        {...form.getInputProps('exceptions')}
        label="Exceptions"
        placeholder={rule ? 'Pick a date to skip' : 'Complete the repeat rule to skip dates'}
        valueFormat="MMMM D, YYYY"
        value={null}
        onChange={addException}
        disabled={!rule}
        minDate={rule?.start}
        maxDate={rule?.until ?? undefined}
        excludeDate={(date) => !rule || !isOccurrence(rule, date)}
      />

      {exceptions.length > 0 && (
        <Stack gap="xs" component="ul" aria-label="Skipped dates" className={classes.list}>
          {exceptions.map((date, index) => (
            <Surface key={date} component="li" withBorder p="sm">
              <Group justify="space-between" wrap="nowrap" gap="sm">
                <Text size="sm">{formatDate(date)}</Text>
                <ActionIcon
                  variant="default"
                  size="lg"
                  aria-label={`Remove ${formatDate(date)}`}
                  onClick={() => form.removeListItem('exceptions', index)}
                >
                  <IconTrash size={18} color="var(--mantine-color-red-text)" />
                </ActionIcon>
              </Group>
            </Surface>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

import { useId } from 'react';
import { Stack, Surface, Text } from '@mantine/core';
import { formatOccurrence, getOccurrences, toRecurrenceRule } from './recurrence';
import type { RecurringEventFormType } from './types';
import { PREVIEW_LIMIT } from './validation';
import classes from './OccurrencePreview.module.css';

interface OccurrencePreviewProps {
  form: RecurringEventFormType;
}

export function OccurrencePreview({ form }: OccurrencePreviewProps) {
  const titleId = useId();
  const startDate = form.useWatchValue('startDate');
  const startTime = form.useWatchValue('startTime');
  const allDay = form.useWatchValue('allDay');
  const recurrence = form.useWatchValue('recurrence');
  const exceptions = form.useWatchValue('exceptions');

  const rule = toRecurrenceRule(startDate, recurrence);
  const occurrences = rule ? getOccurrences(rule, exceptions, PREVIEW_LIMIT) : [];
  const time = allDay || !startTime ? null : startTime;

  return (
    <Surface withBorder p="md">
      <Text id={titleId} size="sm" fw={500} mb="xs">
        Next occurrences
      </Text>
      {occurrences.length === 0 ? (
        <Text size="sm">No occurrences</Text>
      ) : (
        <Stack gap="xs" component="ol" aria-labelledby={titleId} className={classes.list}>
          {occurrences.map((date) => (
            <Text key={date} component="li" size="sm">
              {formatOccurrence(date, time)}
            </Text>
          ))}
        </Stack>
      )}
    </Surface>
  );
}

import type { ComponentType } from 'react';
import { Group, NumberInput, Radio, Text } from '@mantine/core';
import { ExceptionsField } from './ExceptionsField';
import { MonthlyOptions } from './options/MonthlyOptions';
import { WeeklyOptions } from './options/WeeklyOptions';
import { SeriesEndFields } from './SeriesEndFields';
import type { RecurringEventFormType, Repeat } from './types';
import { INTERVAL_UNITS, REPEAT_OPTIONS } from './validation';

interface RecurrenceFieldsProps {
  form: RecurringEventFormType;
}

const REPEAT_OPTION_FIELDS: Partial<Record<Repeat, ComponentType<RecurrenceFieldsProps>>> = {
  weekly: WeeklyOptions,
  monthly: MonthlyOptions,
};

export function RecurrenceFields({ form }: RecurrenceFieldsProps) {
  const repeat = form.useWatchValue('recurrence.repeat');
  const interval = form.useWatchValue('recurrence.interval');
  const OptionFields = REPEAT_OPTION_FIELDS[repeat];

  return (
    <>
      <Radio.Group label="Repeat" {...form.getInputProps('recurrence.repeat')}>
        <Group mt="xs">
          {REPEAT_OPTIONS.map((option) => (
            <Radio key={option.value} value={option.value} label={option.label} />
          ))}
        </Group>
      </Radio.Group>

      {repeat !== 'none' && (
        <>
          <NumberInput
            label="Repeat every"
            placeholder="Interval"
            min={1}
            max={99}
            clampBehavior="none"
            allowNegative={false}
            allowDecimal={false}
            rightSection={<Text size="sm">{INTERVAL_UNITS[repeat][interval === 1 ? 0 : 1]}</Text>}
            rightSectionWidth={72}
            hideControls
            maw={240}
            withAsterisk
            {...form.getInputProps('recurrence.interval')}
          />
          {OptionFields && <OptionFields form={form} />}
          <SeriesEndFields form={form} />
          <ExceptionsField form={form} />
        </>
      )}
    </>
  );
}

import { render, screen, userEvent, within } from '@test-utils';
import { Notifications, notifications } from '@mantine/notifications';
import { RecurringEventForm } from './RecurringEventForm';

type User = ReturnType<typeof userEvent.setup>;

const browserOptions = new Intl.DateTimeFormat().resolvedOptions();

function mockBrowserTimezone(timeZone: string) {
  vi.spyOn(Intl.DateTimeFormat.prototype, 'resolvedOptions').mockReturnValue({
    ...browserOptions,
    timeZone,
  });
}

function renderForm(onSubmit = vi.fn()) {
  const user = userEvent.setup();
  render(
    <>
      <Notifications />
      <RecurringEventForm onSubmit={onSubmit} />
    </>
  );
  return { user, onSubmit };
}

// The asterisk of a required label is part of the label text
const field = (label: string) => screen.getByLabelText(new RegExp(`^${label}( \\*)?$`));
const timezoneInput = () => screen.getByRole('combobox', { name: 'Timezone' });
const dateButton = (label: string) => screen.getByRole('button', { name: new RegExp(`^${label}`) });

async function pickDate(user: User, label: string, day: string) {
  await user.click(dateButton(label));
  const drawer = screen.getByRole('dialog');
  await user.click(within(drawer).getByRole('button', { name: day }));
  await user.click(within(drawer).getByRole('button', { name: 'Save' }));
}

async function typeTime(user: User, label: string, time: string) {
  await user.clear(field(label));
  await user.type(field(label), time);
}

async function fillEvent(user: User) {
  await user.type(field('Title'), 'Team sync');
  await pickDate(user, 'Start date', '21 October 2026');
  await typeTime(user, 'Start time', '09:00');
}

async function chooseRepeat(user: User, repeat: string) {
  await user.click(screen.getByRole('radio', { name: repeat }));
}

async function chooseSeriesEnd(user: User, option: string) {
  await user.click(screen.getByRole('radio', { name: option }));
}

async function submit(user: User) {
  await user.click(screen.getByRole('button', { name: 'Create event' }));
}

function previewItems() {
  return within(screen.getByRole('list', { name: 'Next occurrences' }))
    .getAllByRole('listitem')
    .map((item) => item.textContent);
}

beforeEach(() => {
  vi.useFakeTimers({ toFake: ['Date'] });
  vi.setSystemTime(new Date(2026, 9, 17, 12));
  mockBrowserTimezone('Europe/Berlin');
  mockBrowserTimezone('Europe/Berlin');
});

afterEach(() => {
  vi.useRealTimers();
  vi.restoreAllMocks();
  notifications.clean();
});

describe('event fields', () => {
  it('defaults the timezone to the browser timezone when it is in the list', () => {
    renderForm();
    expect(timezoneInput()).toHaveValue('Berlin');
  });

  it('defaults the timezone to UTC when the browser timezone is not in the list', () => {
    mockBrowserTimezone('Europe/Moscow');
    renderForm();
    expect(timezoneInput()).toHaveValue('UTC');
  });

  it('sets the end to one hour after the start', async () => {
    const { user } = renderForm();
    await fillEvent(user);
    expect(dateButton('End date')).toHaveTextContent('October 21, 2026');
    expect(field('End time')).toHaveValue('10:00');
  });

  it('moves the end with the start while the end was not edited', async () => {
    const { user } = renderForm();
    await fillEvent(user);
    await typeTime(user, 'Start time', '23:30');
    expect(dateButton('End date')).toHaveTextContent('October 22, 2026');
    expect(field('End time')).toHaveValue('00:30');
  });

  it('keeps an edited end when the start changes', async () => {
    const { user } = renderForm();
    await fillEvent(user);
    await typeTime(user, 'End time', '12:00');
    await typeTime(user, 'Start time', '10:00');
    expect(field('End time')).toHaveValue('12:00');
  });

  it('hides the time inputs when All day is on', async () => {
    const { user } = renderForm();
    await user.click(screen.getByRole('switch', { name: 'All day' }));
    expect(screen.queryByLabelText('Start time')).not.toBeInTheDocument();
    expect(screen.queryByLabelText('End time')).not.toBeInTheDocument();
  });
});

